# ─────────────────────────────────────────────
# OUI Loading and Caching
# ─────────────────────────────────────────────


def _load_oui_cache() -> dict[str, str]:
    """
    Charge le cache OUI depuis fichier JSON s'il existe.
    Sinon, retourne la base embarquée.

    Returns:
        dict { "AA:BB:CC": "Vendor Name" }
    """
    if _OUI_FILE.exists():
        try:
            with open(_OUI_FILE, "r", encoding="utf-8") as f:
                cache = json.load(f)
                if isinstance(cache, dict):
                    # IEEE JSON often uses "assignment": "name"
                    # We normalize it here
                    normalized = {}
                    for k, v in cache.items():
                        if isinstance(v, dict) and "assignment" in v:
                            # Official IEEE format
                            normalized[v["assignment"]] = v.get(
                                "organizationName", "Unknown"
                            )
                        else:
                            normalized[k] = v
                    return normalized
        except Exception:
            pass

    return _BUILTIN_OUI


def download_oui_database(force: bool = False) -> bool:
    """
    Télécharge la base OUI officielle depuis IEEE.
    Peut échouer si pas de connexion.

    Args:
        force: Si True, force le téléchargement même si le fichier existe.

    Returns:
        True si succès, False sinon.
    """
    if not force and _OUI_FILE.exists():
        return True

    try:
        req = urllib.request.Request(
            _OUI_URL,
            headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"},
        )
        with urllib.request.urlopen(req, timeout=10) as response:
            content = response.read().decode("utf-8")
            data = json.loads(content)

            # IEEE JSON is usually a list of dicts or a dict with a "data" key
            # Let's handle various formats to be robust
            mapping = {}
            if isinstance(data, list):
                for item in data:
                    oui = item.get("assignment")
                    vendor = item.get("organizationName")
                    if oui and vendor:
                        mapping[oui] = vendor
            elif isinstance(data, dict):
                # Check for "data" key (IEEE format often has it)
                items = data.get("data", data)
                if isinstance(items, list):
                    for item in items:
                        oui = item.get("assignment")
                        vendor = item.get("organizationName")
                        if oui and vendor:
                            mapping[oui] = vendor
                else:
                    # Fallback to direct dict
                    mapping = items

            if mapping:
                _OUI_FILE.parent.mkdir(parents=True, exist_ok=True)
                with open(_OUI_FILE, "w", encoding="utf-8") as f:
                    json.dump(mapping, f, indent=2)

                # Replace the in-memory DB and bust all derived caches so the
                # next mac_to_vendor call rebuilds the normalized prefix tables
                # from the freshly downloaded data.
                global _OUI_CACHE
                _OUI_CACHE = mapping
                with _normalized_lock:
                    global _NORMALIZED_TABLE, _PREFIX_LENGTHS
                    _NORMALIZED_TABLE = None
                    _PREFIX_LENGTHS = []
                _LOOKUP_CACHE.clear()
                return True
    except Exception:
        pass

    return False


# ─────────────────────────────────────────────
# MAC Lookup
# ─────────────────────────────────────────────

_OUI_CACHE: dict[str, str] | None = None


def _get_oui_database() -> dict[str, str]:
    """Retourne la base OUI (cache en mémoire)."""
    global _OUI_CACHE
    if _OUI_CACHE is None:
        _OUI_CACHE = _load_oui_cache()
    return _OUI_CACHE


def is_locally_administered(mac: str) -> bool:
    """
    Check if a MAC address is locally administered (randomized).

    The second-least-significant bit of the first byte of the MAC address
    indicates if it is locally administered.
    If (first_byte & 0x02) is true, it is locally administered.
    """
    if not mac or len(mac) < 2:
        return False
    try:
        first_byte = int(mac[:2], 16)
        return bool(first_byte & 0x02)
    except ValueError:
        return False


# In-process cache of recent lookups keyed by normalized (uppercase, no-sep) MAC.
# Bounded to avoid unbounded memory in long-running services.
_LOOKUP_CACHE: dict[str, str] = {}
_LOOKUP_CACHE_MAX = 4096

# Lazily-built normalized prefix tables so the slow O(N) fallback loop only
# runs once at startup instead of once per lookup.
_NORMALIZED_TABLE: dict[str, str] | None = None
_PREFIX_LENGTHS: list[int] = []
_normalized_lock = threading.Lock()


def _build_normalized_table(
    database: dict[str, str],
) -> tuple[dict[str, str], list[int]]:
    """Strip separators from every OUI key once and collect distinct lengths."""
    table: dict[str, str] = {}
    lengths: set[int] = set()
    for prefix, name in database.items():
        cleaned = prefix.replace(":", "").replace("-", "").replace(".", "").upper()
        if not cleaned:
            continue
        table[cleaned] = name
        lengths.add(len(cleaned))
    return table, sorted(lengths, reverse=True)


def _get_normalized_tables() -> tuple[dict[str, str], list[int]]:
    global _NORMALIZED_TABLE, _PREFIX_LENGTHS
    if _NORMALIZED_TABLE is not None:
        return _NORMALIZED_TABLE, _PREFIX_LENGTHS
    with _normalized_lock:
        # Double-checked: another thread may have built the table while we waited.
        if _NORMALIZED_TABLE is None:
            _NORMALIZED_TABLE, _PREFIX_LENGTHS = _build_normalized_table(
                _get_oui_database()
            )
    return _NORMALIZED_TABLE, _PREFIX_LENGTHS


def reset_caches() -> None:
    """Drop the lookup and normalized tables (used after refreshing the DB)."""
    global _NORMALIZED_TABLE, _PREFIX_LENGTHS, _OUI_CACHE
    with _normalized_lock:
        _NORMALIZED_TABLE = None
        _PREFIX_LENGTHS = []
    _LOOKUP_CACHE.clear()
    _OUI_CACHE = None


def mac_to_vendor(mac: str) -> str:
    """
    Convertit une adresse MAC en nom de vendor via OUI lookup.

    Utilise les 3 premiers octets (OUI) puis, en fallback, les préfixes plus longs
    (28 ou 36 bits) que l'IEEE assigne pour les MA-M / MA-S.

    Retourne :
      - le nom du fabricant
      - ``"Locally Administered (Randomized)"`` si bit LA positionné
      - ``"Unknown"`` si l'entrée est invalide ou inconnue
    """
    if not isinstance(mac, str) or not mac:
        return "Unknown"

    # Normalize before cache lookup so "AA:BB:CC:DD:EE:01" and
    # "aa:bb:cc:dd:ee:01" (and other separator/case variants) share one entry.
    clean_mac = mac.strip().replace(":", "").replace("-", "").replace(".", "").upper()

    if not clean_mac or not all(c in "0123456789ABCDEF" for c in clean_mac):
        return "Unknown"

    cached = _LOOKUP_CACHE.get(clean_mac)
    if cached is not None:
        return cached

    if len(clean_mac) < 6:
        return "Unknown"

    oui_database = _get_oui_database()
    oui_6 = clean_mac[:6]
    oui_formatted = f"{oui_6[0:2]}:{oui_6[2:4]}:{oui_6[4:6]}"

    # Fast path: 24-bit OUI exact match.
    for key in (oui_formatted, oui_6):
        vendor = oui_database.get(key)
        if vendor:
            if vendor in ("Generic Device", "Broadcast") and len(clean_mac) not in (
                6,
                12,
            ):
                return "Unknown"
            _remember_lookup(clean_mac, vendor)
            return vendor

    if len(clean_mac) < 12:
        return "Unknown"

    if is_locally_administered(clean_mac):
        result = "Locally Administered (Randomized)"
        _remember_lookup(clean_mac, result)
        return result

    # Fallback: variable-width prefix match against the pre-normalized table.
    # We try the longest prefix first so MA-S (36 bits) wins over MA-M (28 bits)
    # which wins over the standard 24-bit OUI.
    table, lengths = _get_normalized_tables()
    for length in lengths:
        if length < 6 or length > len(clean_mac):
            continue
        candidate = clean_mac[:length]
        name = table.get(candidate)
        if name:
            _remember_lookup(clean_mac, name)
            return name

    return "Unknown"


def _remember_lookup(key: str, vendor: str) -> None:
    """Insert into the bounded lookup cache. Key must already be normalized."""
    if len(_LOOKUP_CACHE) >= _LOOKUP_CACHE_MAX:
        # Drop one arbitrary entry — keeps cache bounded without LRU bookkeeping.
        try:
            _LOOKUP_CACHE.pop(next(iter(_LOOKUP_CACHE)))
        except StopIteration:
            pass
    _LOOKUP_CACHE[key] = vendor


# ─────────────────────────────────────────────
# Device enrichment
# ─────────────────────────────────────────────


def enrich_devices(devices: list[Device]) -> list[Device]:
    """
    Enrichit chaque Device avec son vendor MAC via lookup OUI.

    Cette fonction est appelée en début du pipeline (après arp_scan).
    Le lookup est purement local (pas d'I/O), donc on n'a pas besoin
    de paralléliser — la pré-normalisation de la table OUI évite la
    boucle O(N) qui était le bottleneck historique.
    """
    _log.info("MAC OUI lookup on %d device(s)", len(devices))

    # Warm the normalized tables once for the batch instead of per-device.
    _get_normalized_tables()

    for device in devices:
        vendor = mac_to_vendor(device.mac)
        device.mac_vendor = vendor
        _log.debug("  %s | %s | %s", device.ip, device.mac, vendor)

    return devices
